[CmdletBinding()]
param([string]$ProjectRoot='.',[Parameter(Mandatory=$true)][string]$CurrentStatePath,[switch]$Apply)
$ErrorActionPreference='Stop';$Root=(Resolve-Path -LiteralPath $ProjectRoot).Path;$Agy=Join-Path $Root '.agy';$ProgressPath=Join-Path $Agy 'PROGRESS_STATE.json';$PolicyPath=Join-Path $Agy 'PROGRESS_POLICY.json';$Node=(Get-Command node -ErrorAction Stop).Source;$Engine=Join-Path $Root 'scripts\control-plane\progress-guard.cjs';if(!(Test-Path $Engine)){throw "Progress engine missing: $Engine"};$Previous=if(Test-Path $ProgressPath){Get-Content $ProgressPath -Raw|ConvertFrom-Json}else{@{}};$Current=Get-Content (Resolve-Path $CurrentStatePath) -Raw|ConvertFrom-Json;$Policy=if(Test-Path $PolicyPath){Get-Content $PolicyPath -Raw|ConvertFrom-Json}else{[pscustomobject]@{consecutive_no_progress_limit=2;same_failure_limit=2}}
$Current|Add-Member -NotePropertyName consecutive_no_progress_limit -NotePropertyValue ([int]$Policy.consecutive_no_progress_limit) -Force;$Current|Add-Member -NotePropertyName same_failure_limit -NotePropertyValue ([int]$Policy.same_failure_limit) -Force
$Payload=[ordered]@{previous=$Previous;current=$Current}|ConvertTo-Json -Depth 50 -Compress;$Temp=[IO.Path]::GetTempFileName();try{[IO.File]::WriteAllText($Temp,$Payload,[Text.UTF8Encoding]::new($false));$Out=Get-Content $Temp -Raw|& $Node $Engine;if($LASTEXITCODE-ne0){throw 'Progress engine failed.'};$State=$Out|ConvertFrom-Json;if($Apply){[IO.File]::WriteAllText($ProgressPath,($State|ConvertTo-Json -Depth 50),[Text.UTF8Encoding]::new($false));Write-Host "Progress state: $($State.status); observation $($State.observations_count); no-progress $($State.consecutive_no_progress)."}else{$State|ConvertTo-Json -Depth 50}}finally{Remove-Item $Temp -Force -ErrorAction SilentlyContinue}
